<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { Check, CircleCheck, Download, QuestionFilled, RefreshRight } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { useSystemStore } from '../stores/system'
import { activateModelProvider, downloadLocalModel, fetchLocalModels, fetchModelProviders, testModelProvider, type LocalModelItem, type ModelProviderConfig } from '../api/sys'

const systemStore = useSystemStore()
const saving = ref(false), verifyingEmbedding = ref(false), embeddingVerified = ref(false)
const providers = ref<ModelProviderConfig[]>([]), localModels = ref<LocalModelItem[]>([])
const primaryModel = ref<(string | number)[]>([]), embeddingProvider = ref<(string | number)[]>([])
const localModelId = ref('')
const embeddingSource = ref<'local' | 'service'>('local')
let pollTimer: number | undefined
const knownProviders = new Set(['deepseek','qwen','openai','anthropic','gemini','azure-openai','zhipu','moonshot','baidu-qianfan','tencent-hunyuan','minimax','siliconflow','groq','mistral','cohere','together','custom','ollama','vllm'])
function isEnabled(item:ModelProviderConfig){return item.enabled===true||item.enabled===1||String(item.enabled)==='1'}
function isEmbedding(name:string){return /(embed|bge|e5|m3e|gte|text2vec|jina-embeddings)/i.test(name)}
const enabledProviders=computed(()=>providers.value.filter(item=>knownProviders.has(item.providerName)&&isEnabled(item)))
const modelTree=computed(()=>enabledProviders.value.filter(item=>!isEmbedding(item.modelName)&&!/(rerank)/i.test(item.modelName)).map(item=>({value:item.id,label:item.providerName,children:[{value:item.modelName,label:item.modelName}]})))
const embeddingTree=computed(()=>enabledProviders.value.filter(item=>isEmbedding(item.modelName)).map(item=>({value:item.id,label:item.providerName,children:[{value:item.modelName,label:item.modelName}]})))
const activeDownload=computed(()=>localModels.value.find(item=>item.status==='downloading')??localModels.value.find(item=>item.status==='queued'))
async function loadLocalModels(){localModels.value=await fetchLocalModels();const active=localModels.value.some(item=>item.status==='queued'||item.status==='downloading');if(active&&!pollTimer)pollTimer=window.setInterval(loadLocalModels,1200);if(!active&&pollTimer){clearInterval(pollTimer);pollTimer=undefined}}
async function startDownload(item:LocalModelItem){if(item.status==='queued'||item.status==='downloading')return;await downloadLocalModel(item.id);ElMessage.success(`${item.name} 已加入下载队列`);await loadLocalModels()}
function optionStyle(item:LocalModelItem){return item.status==='downloading'?{background:`linear-gradient(to right,#e5f7eb ${item.progress}%,transparent ${item.progress}%)`}:undefined}
function chooseLocalModel(id:string){const item=localModels.value.find(model=>model.id===id);if(!item?.installed){localModelId.value='';ElMessage.warning('该模型尚未下载，请点击右侧下载图标');return}systemStore.form.embeddingModelPath=item.path;embeddingVerified.value=false}
async function verifyEmbedding(){verifyingEmbedding.value=true;embeddingVerified.value=false;try{if(embeddingSource.value==='local'){await systemStore.verifyModel(systemStore.form.embeddingModelPath);embeddingVerified.value=systemStore.modelVerifyStatus==='success';if(!embeddingVerified.value)ElMessage.error(systemStore.modelVerifyMessage||'模型验证失败')}else{const provider=enabledProviders.value.find(item=>item.id===Number(embeddingProvider.value[0]));if(!provider)throw new Error('请选择 Embedding 模型服务');const result=await testModelProvider({id:provider.id,providerName:provider.providerName,providerType:provider.providerType,endpoint:provider.endpoint});embeddingVerified.value=result.success;if(!result.success)ElMessage.error(result.message)}}finally{verifyingEmbedding.value=false}}
async function save(){saving.value=true;try{const id=Number(primaryModel.value[0]);if(!id)throw new Error('请选择已启用的问答模型');await systemStore.saveSettings();await activateModelProvider(id);ElMessage.success('模型设置已保存并生效')}catch(error){ElMessage.error((error as Error).message||'保存失败')}finally{saving.value=false}}
onMounted(async()=>{const[,,rows]=await Promise.all([systemStore.loadRuntimeConfig(false),loadLocalModels(),fetchModelProviders()]);providers.value=rows;const installed=localModels.value.find(item=>item.installed&&item.path===systemStore.form.embeddingModelPath)??localModels.value.find(item=>item.installed);if(installed){localModelId.value=installed.id;systemStore.form.embeddingModelPath=installed.path}else{localModelId.value='';systemStore.form.embeddingModelPath=''}void systemStore.refreshDevices();const current=systemStore.runtimeConfig?.model.activeMode==='online'?systemStore.runtimeConfig?.model.online.modelName:systemStore.runtimeConfig?.model.offline.ollama.defaultModel;const active=enabledProviders.value.find(item=>item.modelName===current);if(active)primaryModel.value=[active.id,active.modelName]})
onUnmounted(()=>{if(pollTimer)clearInterval(pollTimer)})
</script>
<template><div class="model-settings" v-loading="systemStore.loading"><header class="page-header"><div><h1>模型设置</h1><p>只显示已启用且符合当前用途的模型。</p></div><el-button type="primary" :loading="saving" @click="save">保存</el-button></header><el-card shadow="never" header="文本模型"><el-form label-position="top"><el-form-item><template #label><span>AI 问答主模型 <el-tooltip content="用于知识库问答与普通对话，只显示文本对话模型"><el-icon class="help"><QuestionFilled/></el-icon></el-tooltip></span></template><el-cascader v-model="primaryModel" :options="modelTree" :show-all-levels="true" placeholder="选择已启用的文本模型" class="wide-control"/></el-form-item></el-form></el-card><el-card shadow="never" header="文本嵌入模型" class="mt"><el-tabs v-model="embeddingSource"><el-tab-pane label="本地模型（默认）" name="local"><el-form label-position="top"><el-form-item><template #label><span>本地 Embedding 模型 <el-tooltip content="模型默认下载到当前操作系统用户家目录的 .jc-rag/models/embedding/"><el-icon class="help"><QuestionFilled/></el-icon></el-tooltip></span></template><div class="model-input-row"><el-select v-model="localModelId" class="download-select" filterable placeholder="查找并选择已下载的模型" @change="chooseLocalModel"><el-option v-for="item in localModels" :key="item.id" :label="item.name" :value="item.id"><div class="download-option" :style="optionStyle(item)"><div><strong>{{item.name}}</strong><small>{{item.repoId}}</small></div><span v-if="item.installed" class="installed"><CircleCheck/> 已下载</span><el-button v-else circle text :icon="Download" :loading="item.status==='downloading'" :title="item.status==='queued'?'等待下载':item.status==='downloading'?`下载中 ${item.progress}%`:'下载模型'" @mousedown.prevent.stop @click.stop="startDownload(item)"/></div></el-option></el-select><el-button class="verify-button" :type="embeddingVerified?'success':'default'" :icon="embeddingVerified?CircleCheck:Check" :loading="verifyingEmbedding" @click="verifyEmbedding">{{embeddingVerified?'验证通过':'验证模型'}}</el-button></div><div v-if="activeDownload" class="download-status">{{activeDownload.name}}：{{activeDownload.message}} {{activeDownload.progress}}%</div></el-form-item><el-form-item><template #label><span>运行设备 <el-tooltip content="自动检测当前服务器上的 CPU 与 GPU，并优先选择性能更强的可用设备"><el-icon class="help"><QuestionFilled/></el-icon></el-tooltip></span></template><div class="model-input-row"><el-select v-model="systemStore.form.embeddingDevice" class="download-select"><el-option v-for="item in systemStore.devices" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-button text :icon="RefreshRight" @click="systemStore.refreshDevices">刷新设备</el-button></div></el-form-item></el-form></el-tab-pane><el-tab-pane label="使用模型服务" name="service"><div class="model-input-row"><el-cascader v-model="embeddingProvider" :options="embeddingTree" :show-all-levels="true" placeholder="仅显示已启用的 Embedding 模型" class="download-select"/><el-button class="verify-button" :type="embeddingVerified?'success':'default'" :icon="embeddingVerified?CircleCheck:Check" :loading="verifyingEmbedding" @click="verifyEmbedding">{{embeddingVerified?'验证通过':'验证模型'}}</el-button></div></el-tab-pane></el-tabs></el-card></div></template>
<style scoped>.model-settings{max-width:1120px;margin:0 auto}.page-header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}.page-header h1{margin:0;font-size:22px}.page-header p{margin:8px 0 0;color:#64748b}.mt{margin-top:14px}.help{color:#909399;cursor:help;vertical-align:-2px}.wide-control{width:100%;max-width:760px}.model-input-row{display:grid;grid-template-columns:minmax(520px,760px) auto;align-items:center;gap:10px;width:100%}.download-select{width:100%!important;min-width:520px}.verify-button{height:32px;white-space:nowrap}.download-option{display:flex;align-items:center;justify-content:space-between;gap:16px;width:100%;min-height:46px;margin:-8px -12px;padding:8px 12px}.download-option>div{display:flex;flex-direction:column;line-height:1.3;min-width:0}.download-option strong,.download-option small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.download-option small{color:#909399}.installed{display:flex;align-items:center;gap:4px;color:#16a34a}.installed svg{width:16px}.download-status{margin-top:7px;color:#16a34a;font-size:13px}@media(max-width:800px){.model-input-row{grid-template-columns:1fr}.download-select{min-width:0}}</style>
